<?php
declare(strict_types=1);
require_once __DIR__.'/global_brand_v704.php';

function v700_tid(): int { return function_exists('tenant_id') ? (int)tenant_id() : 0; }
function v700_city_id(): int { try{return function_exists('current_city_id')?(int)(current_city_id()?:0):0;}catch(Throwable $e){return 0;} }
function v700_user(): ?array { return function_exists('current_user') ? current_user() : null; }
function v700_setting(string $key,string $default=''): string { try{return function_exists('setting')?(string)setting($key,$default):$default;}catch(Throwable $e){return $default;} }
function v700_bool(string $key,bool $default=true): bool { try{return function_exists('setting_bool')?setting_bool($key,$default):$default;}catch(Throwable $e){return $default;} }
function v700_table(string $table): bool { static $cache=[]; if(array_key_exists($table,$cache))return $cache[$table]; try{$q=db()->prepare('SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?');$q->execute([$table]);return $cache[$table]=((int)$q->fetchColumn()>0);}catch(Throwable $e){try{$q=db()->query('SHOW TABLES');$rows=$q?$q->fetchAll(PDO::FETCH_COLUMN):[];return $cache[$table]=in_array($table,$rows,true);}catch(Throwable $ignore){return $cache[$table]=false;}} }
function v701_log(Throwable $e,string $context='public'): string { $id='V701-'.strtoupper(substr(hash('sha256',microtime(true).'|'.random_int(1,PHP_INT_MAX)),0,10)); error_log('[ShahkotPK '.$id.']['.$context.'] '.$e::class.': '.$e->getMessage().' @ '.$e->getFile().':'.$e->getLine()); return $id; }
function v701_public_error(Throwable $e,string $title='This service is temporarily unavailable'): void { $id=v701_log($e,'route'); if(ob_get_level()>0){@ob_clean();} http_response_code(503); global $config; $brand=function_exists('tenant_brand')?tenant_brand('site_name','ShahkotPK'):($config['app_name']??'ShahkotPK'); echo '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/assets/super-app-7.0.1.css?v=701"><title>'.e($title).' - '.e($brand).'</title></head><body class="v700-body"><main class="v701-error-wrap"><section class="v701-error-card"><div class="v701-error-icon">!</div><h1>'.e($title).'</h1><p>ShahkotPK could not load this module completely. The problem has been logged safely. Please refresh once; if it continues, share this error ID with the administrator.</p><b>Error ID: '.e($id).'</b><div class="v700-actions"><a class="v700-btn primary" href="/app.php">Back to Super App</a><a class="v700-btn ghost" href="javascript:location.reload()">Retry</a></div></section></main></body></html>'; }
function v701_install_exception_handler(): void { static $done=false;if($done)return;$done=true;set_exception_handler(static function(Throwable $e): void {v701_public_error($e);}); }
v701_install_exception_handler();
function v700_money(float $n): string { return 'Rs '.number_format($n,0); }
function v700_next(string $prefix): string { return strtoupper($prefix).'-'.date('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(5)),0,8)); }
function v700_login_url(string $return='/app.php'): string { return '/login.php?return='.rawurlencode($return); }
function v700_require_user(): array { $u=v700_user(); if(!$u){header('Location: '.v700_login_url($_SERVER['REQUEST_URI']??'/app.php'),true,302);exit;} return $u; }
function v700_slug(string $s): string { $s=mb_strtolower(trim($s));$s=preg_replace('/[^\pL\pN]+/u','-',$s)??'';$s=trim($s,'-');return $s!==''?$s:'item-'.substr(bin2hex(random_bytes(4)),0,8); }
function v700_module_enabled(string $module): bool {
    $module=in_array($module,['education','transport','tourism','pwa'],true)?$module:'pwa';
    try{$q=db()->prepare('SELECT education_enabled,transport_enabled,tourism_enabled,pwa_enabled FROM tenant_superapp_settings_v700 WHERE tenant_id=? LIMIT 1');$q->execute([v700_tid()]);$r=$q->fetch();if(!$r)return true;$map=['education'=>'education_enabled','transport'=>'transport_enabled','tourism'=>'tourism_enabled','pwa'=>'pwa_enabled'];return (bool)$r[$map[$module]];}catch(Throwable $e){return true;}
}
function v700_tenant_settings(): array {
    $d=['education_enabled'=>1,'transport_enabled'=>1,'tourism_enabled'=>1,'pwa_enabled'=>1,'education_approval_required'=>1,'transport_approval_required'=>1,'tourism_approval_required'=>1,'ride_enabled'=>1,'delivery_enabled'=>1,'hotel_booking_enabled'=>1,'restaurant_booking_enabled'=>1,'app_name'=>'ShahkotPK Super App'];
    try{$q=db()->prepare('SELECT * FROM tenant_superapp_settings_v700 WHERE tenant_id=? LIMIT 1');$q->execute([v700_tid()]);$r=$q->fetch();return $r?array_merge($d,$r):$d;}catch(Throwable $e){return $d;}
}
function v700_track(string $module,string $action,string $entityType='',?int $entityId=null): void { try{$u=v700_user();db()->prepare('INSERT INTO superapp_activity_v700(tenant_id,user_id,module,action,entity_type,entity_id,created_at) VALUES(?,?,?,?,?,?,NOW())')->execute([v700_tid(),$u?(int)$u['id']:null,$module,$action,$entityType?:null,$entityId]);}catch(Throwable $e){} }
function v700_one(string $table,int $id,string $extra='1=1'): ?array { try{$q=db()->prepare("SELECT * FROM `$table` WHERE id=? AND tenant_id=? AND $extra LIMIT 1");$q->execute([$id,v700_tid()]);return $q->fetch()?:null;}catch(Throwable $e){return null;} }
function v700_rows(string $sql,array $params=[]): array { try{$q=db()->prepare($sql);$q->execute($params);return $q->fetchAll()?:[];}catch(Throwable $e){return [];} }
function v700_count(string $table,string $where='1=1',array $params=[]): int { if(!v700_table($table))return 0;try{$q=db()->prepare("SELECT COUNT(*) FROM `$table` WHERE tenant_id=? AND $where");$q->execute(array_merge([v700_tid()],$params));return (int)$q->fetchColumn();}catch(Throwable $e){return 0;} }
function v700_public_header(string $title,string $subtitle,string $active=''): void {
    global $config;$brand=function_exists('gb704_brand_name')?gb704_brand_name('ShahkotPK'):(function_exists('tenant_brand')?tenant_brand('site_name','ShahkotPK'):($config['app_name']??'ShahkotPK'));$u=v700_user();
    $logo=function_exists('gb704_picture')?gb704_picture('superapp',$brand):'';$brandMarkup=$logo!==''?$logo.'<span class="gb704-module-label">Super App</span>':'<i>S</i><span><b>'.e($brand).'</b><small>City Super App</small></span>';
    echo '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#081b2d"><meta name="csrf-token" content="'.e(csrf_token()).'"><meta name="description" content="'.e($subtitle).'"><link rel="manifest" href="/super-app-manifest.webmanifest"><link rel="stylesheet" href="/assets/super-app-7.0.1.css?v=701">'.(function_exists('gb704_asset_tag')?gb704_asset_tag():'').'<script defer src="/assets/super-app-7.0.0.js?v=700"></script><title>'.e($title).' - '.e($brand).'</title></head><body class="v700-body"><header class="v700-top"><div class="v700-shell v700-nav"><a class="v700-brand gb704-brand" href="/app.php">'.$brandMarkup.'</a><button class="v700-menu" data-v700-menu>☰</button><nav data-v700-nav><a '.($active==='app'?'class="active" ':'').'href="/app.php">Super App</a>'.(v700_module_enabled('education')?'<a '.($active==='education'?'class="active" ':'').'href="/education.php">Education</a>':'').(v700_module_enabled('transport')?'<a '.($active==='transport'?'class="active" ':'').'href="/transport.php">Transport</a>':'').(v700_module_enabled('tourism')?'<a '.($active==='tourism'?'class="active" ':'').'href="/tourism.php">Tourism</a>':'').'<a href="/smart-city.php">Smart City</a><a href="/health-network.php">Health</a></nav><a class="v700-account" href="'.e($u?'/citizen.php':v700_login_url('/app.php')).'">'.e($u?'My Dashboard':'Login').' ↗</a></div></header>';
}
function v700_public_footer(): void { echo '<footer class="v700-footer"><div class="v700-shell"><div><b>ShahkotPK Super App</b><span>Education · Transport · Tourism · Smart City</span></div><nav><a href="/education.php">Education</a><a href="/transport.php">Transport</a><a href="/tourism.php">Tourism</a><a href="/citizen.php">Citizen Dashboard</a></nav></div></footer><nav class="v700-mobile-nav"><a href="/app.php"><i>⌂</i><span>Home</span></a><a href="/education.php"><i>▤</i><span>Study</span></a><a href="/transport.php"><i>↔</i><span>Travel</span></a><a href="/tourism.php"><i>✦</i><span>Explore</span></a><a href="/citizen.php"><i>◉</i><span>Me</span></a></nav></body></html>'; }
function v700_status_badge(string $s): string { $safe=preg_replace('/[^a-z0-9_-]/i','-',strtolower($s));return '<span class="v700-badge '.e($safe).'">'.e(ucwords(str_replace('_',' ',$s))).'</span>'; }

function v700_education_stats(): array { return ['institutions'=>v700_count('edu_institutions_v700',"status='active'"),'programs'=>v700_count('edu_programs_v700',"status='active'"),'applications'=>v700_count('edu_applications_v700'),'enrollments'=>v700_count('edu_enrollments_v700',"status='active'")]; }
function v700_transport_stats(): array { return ['operators'=>v700_count('transport_operators_v700',"status='active'"),'vehicles'=>v700_count('transport_vehicles_v700',"status IN ('active','available')"),'trips'=>v700_count('transport_trips_v700',"status IN ('scheduled','boarding','departed')"),'rides'=>v700_count('ride_requests_v700',"status NOT IN ('completed','cancelled')")]; }
function v700_tourism_stats(): array { return ['attractions'=>v700_count('tourism_attractions_v700',"status='active'"),'hotels'=>v700_count('tourism_hotels_v700',"status='active'"),'restaurants'=>v700_count('tourism_restaurants_v700',"status='active'"),'packages'=>v700_count('tourism_packages_v700',"status='active'")]; }

