function v700_create_education_application(int $uid,array $d): int {
    $institution=(int)($d['institution_id']??0);$program=(int)($d['program_id']??0);$name=trim((string)($d['applicant_name']??''));$phone=trim((string)($d['phone']??''));
    if($institution<1||$name===''||$phone==='')throw new RuntimeException('Institution, applicant name and phone are required.');
    $ref=v700_next('EDU');$q=db()->prepare("INSERT INTO edu_applications_v700(tenant_id,city_id,reference_no,user_id,institution_id,program_id,applicant_name,phone,email,previous_qualification,message,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,'submitted',NOW(),NOW())");$q->execute([v700_tid(),v700_city_id(),$ref,$uid,$institution,$program?:null,mb_substr($name,0,190),mb_substr($phone,0,80),trim((string)($d['email']??''))?:null,trim((string)($d['previous_qualification']??''))?:null,trim((string)($d['message']??''))?:null]);$id=(int)db()->lastInsertId();v700_track('education','application','application',$id);return $id;
}
function v700_create_transport_booking(int $uid,int $tripId,int $seats,string $pickup=''): int {
    $seats=max(1,min(8,$seats));$ref=v700_next('BUS');db()->beginTransaction();try{
      $q=db()->prepare("SELECT * FROM transport_trips_v700 WHERE id=? AND tenant_id=? AND status IN ('scheduled','boarding') FOR UPDATE");$q->execute([$tripId,v700_tid()]);$trip=$q->fetch();if(!$trip)throw new RuntimeException('Selected trip is not available.');if((int)$trip['available_seats']<$seats)throw new RuntimeException('Not enough seats are available on this trip.');
      db()->prepare("INSERT INTO transport_bookings_v700(tenant_id,user_id,trip_id,booking_no,seats,pickup_point,total_amount,payment_status,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,'unpaid','booked',NOW(),NOW())")->execute([v700_tid(),$uid,$tripId,$ref,$seats,mb_substr(trim($pickup),0,190)?:null,round((float)$trip['fare']*$seats,2)]);$id=(int)db()->lastInsertId();
      db()->prepare('UPDATE transport_trips_v700 SET available_seats=GREATEST(0,available_seats-?),updated_at=NOW() WHERE id=? AND tenant_id=?')->execute([$seats,$tripId,v700_tid()]);db()->commit();v700_track('transport','booking','booking',$id);return $id;
    }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
function v700_create_ride(int $uid,array $d): int { $pickup=trim((string)($d['pickup_address']??''));$dest=trim((string)($d['destination_address']??''));if($pickup===''||$dest==='')throw new RuntimeException('Pickup and destination are required.');$ref=v700_next('RIDE');$q=db()->prepare("INSERT INTO ride_requests_v700(tenant_id,user_id,request_no,service_type,pickup_address,destination_address,pickup_latitude,pickup_longitude,destination_latitude,destination_longitude,scheduled_at,notes,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?, 'requested',NOW(),NOW())");$q->execute([v700_tid(),$uid,$ref,in_array(($d['service_type']??'ride'),['ride','rickshaw','taxi','bike'],true)?$d['service_type']:'ride',$pickup,$dest,($d['pickup_latitude']??'')!==''?(float)$d['pickup_latitude']:null,($d['pickup_longitude']??'')!==''?(float)$d['pickup_longitude']:null,($d['destination_latitude']??'')!==''?(float)$d['destination_latitude']:null,($d['destination_longitude']??'')!==''?(float)$d['destination_longitude']:null,trim((string)($d['scheduled_at']??''))?:null,trim((string)($d['notes']??''))?:null]);$id=(int)db()->lastInsertId();v700_track('transport','ride_request','ride',$id);return $id; }
function v700_create_delivery(int $uid,array $d): int { $from=trim((string)($d['pickup_address']??''));$to=trim((string)($d['dropoff_address']??''));if($from===''||$to==='')throw new RuntimeException('Pickup and drop-off are required.');$ref=v700_next('DEL');$q=db()->prepare("INSERT INTO delivery_orders_v700(tenant_id,user_id,delivery_no,delivery_type,pickup_name,pickup_phone,pickup_address,dropoff_name,dropoff_phone,dropoff_address,item_description,cod_amount,delivery_fee,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,'requested',NOW(),NOW())");$q->execute([v700_tid(),$uid,$ref,in_array(($d['delivery_type']??'parcel'),['parcel','document','food','grocery','commerce'],true)?$d['delivery_type']:'parcel',mb_substr(trim((string)($d['pickup_name']??'')),0,190)?:null,mb_substr(trim((string)($d['pickup_phone']??'')),0,80)?:null,$from,mb_substr(trim((string)($d['dropoff_name']??'')),0,190)?:null,mb_substr(trim((string)($d['dropoff_phone']??'')),0,80)?:null,$to,trim((string)($d['item_description']??''))?:null,max(0,(float)($d['cod_amount']??0)),max(0,(float)($d['delivery_fee']??0))]);$id=(int)db()->lastInsertId();v700_track('transport','delivery','delivery',$id);return $id; }
function v700_create_hotel_booking(int $uid,array $d): int { $hotel=(int)($d['hotel_id']??0);$room=(int)($d['room_id']??0);$in=(string)($d['check_in']??'');$out=(string)($d['check_out']??'');if($hotel<1||$room<1||$in===''||$out===''||strtotime($out)<=strtotime($in))throw new RuntimeException('Select a valid room and stay dates.');$r=v700_one('tourism_hotel_rooms_v700',$room,'status=\'active\'');if(!$r|| (int)$r['hotel_id']!==$hotel)throw new RuntimeException('Room is not available.');$q=db()->prepare("SELECT COUNT(*) FROM hotel_bookings_v700 WHERE tenant_id=? AND room_id=? AND status IN ('requested','confirmed','checked_in') AND NOT(check_out<=? OR check_in>=?)");$q->execute([v700_tid(),$room,$in,$out]);if((int)$q->fetchColumn()>=(int)$r['quantity'])throw new RuntimeException('This room type is fully booked for the selected dates.');$nights=max(1,(int)ceil((strtotime($out)-strtotime($in))/86400));$ref=v700_next('HOTEL');$q=db()->prepare("INSERT INTO hotel_bookings_v700(tenant_id,user_id,hotel_id,room_id,booking_no,check_in,check_out,guests,total_amount,payment_status,status,guest_name,guest_phone,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,'unpaid','requested',?,?,NOW(),NOW())");$q->execute([v700_tid(),$uid,$hotel,$room,$ref,$in,$out,max(1,(int)($d['guests']??1)),round((float)$r['price_per_night']*$nights,2),mb_substr(trim((string)($d['guest_name']??'')),0,190)?:null,mb_substr(trim((string)($d['guest_phone']??'')),0,80)?:null]);$id=(int)db()->lastInsertId();v700_track('tourism','hotel_booking','hotel_booking',$id);return $id; }
function v700_create_restaurant_booking(int $uid,array $d): int { $restaurant=(int)($d['restaurant_id']??0);$date=trim((string)($d['booking_date']??''));$time=trim((string)($d['booking_time']??''));if($restaurant<1||$date===''||$time==='')throw new RuntimeException('Restaurant, date and time are required.');$ref=v700_next('TABLE');$q=db()->prepare("INSERT INTO restaurant_bookings_v700(tenant_id,user_id,restaurant_id,booking_no,booking_date,booking_time,guests,customer_name,customer_phone,special_request,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,'requested',NOW(),NOW())");$q->execute([v700_tid(),$uid,$restaurant,$ref,$date,$time,max(1,(int)($d['guests']??2)),mb_substr(trim((string)($d['customer_name']??'')),0,190),mb_substr(trim((string)($d['customer_phone']??'')),0,80),trim((string)($d['special_request']??''))?:null]);$id=(int)db()->lastInsertId();v700_track('tourism','restaurant_booking','restaurant_booking',$id);return $id; }
function v700_create_tour_booking(int $uid,array $d): int { $package=(int)($d['package_id']??0);$date=trim((string)($d['travel_date']??''));$pkg=v700_one('tourism_packages_v700',$package,"status='active'");if(!$pkg||$date==='')throw new RuntimeException('Package and travel date are required.');$people=max(1,(int)($d['people']??1));if((int)$pkg['capacity']>0){$q=db()->prepare("SELECT COALESCE(SUM(people),0) FROM tourism_package_bookings_v700 WHERE tenant_id=? AND package_id=? AND travel_date=? AND status IN ('requested','confirmed')");$q->execute([v700_tid(),$package,$date]);if(((int)$q->fetchColumn()+$people)>(int)$pkg['capacity'])throw new RuntimeException('Not enough package capacity is available for this date.');}$ref=v700_next('TOUR');$q=db()->prepare("INSERT INTO tourism_package_bookings_v700(tenant_id,user_id,package_id,booking_no,travel_date,people,total_amount,payment_status,status,customer_name,customer_phone,created_at,updated_at) VALUES(?,?,?,?,?,?,?,'unpaid','requested',?,?,NOW(),NOW())");$q->execute([v700_tid(),$uid,$package,$ref,$date,$people,round((float)$pkg['price_per_person']*$people,2),mb_substr(trim((string)($d['customer_name']??'')),0,190),mb_substr(trim((string)($d['customer_phone']??'')),0,80)]);$id=(int)db()->lastInsertId();v700_track('tourism','tour_booking','tour_booking',$id);return $id; }


function v700_staff_scope_ids(int $userId,string $scopeType): ?array {
    if($userId<1)return null;
    if(function_exists('is_super_admin')&&is_super_admin(v700_user()))return null;
    try{$q=db()->prepare('SELECT scope_type,scope_id FROM superapp_staff_v700 WHERE tenant_id=? AND user_id=? AND status=1');$q->execute([v700_tid(),$userId]);$rows=$q->fetchAll()?:[];if(!$rows)return null;foreach($rows as $r)if(empty($r['scope_type'])||empty($r['scope_id']))return null;$ids=[];foreach($rows as $r)if((string)$r['scope_type']===$scopeType)$ids[]=(int)$r['scope_id'];return array_values(array_unique(array_filter($ids)));}catch(Throwable $e){return null;}
}
function v700_staff_scope_allows(int $userId,string $scopeType,int $scopeId): bool { $ids=v700_staff_scope_ids($userId,$scopeType);return $ids===null||in_array($scopeId,$ids,true); }
